/// <summary>
/// The MobDocumentNode is a class matching a XML tag in an xml document.
/// </summary>
class MobDocumentNode extends TFMDocumentNode
{

}

Method.Source:
protected void new(int64 _nodeID, MobDocumentNode _parent, MobDocumentNodes _nodes)
{
    parentID        = _parent == null ? 0 : _parent.getnodeID();        
    children        = new Map(Types::String,Types::int64);
    attributes      = new Map(Types::String,Types::String);
    childNameCount  = new Map(Types::String,types::Integer);
    nodeID          = _nodeID;
    owner           = _nodes;
    cData           = null;
}

public static MobDocumentNode Construct(int64 _nodeID, MobDocumentNode _parent, MobDocumentNodes _nodes)
{
    return new MobDocumentNode(_nodeID,  _parent, _nodes);
}
